using ERP.NSQuell.Models.ViewModels.Produccion;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Data.SqlClient;
using System.Data;
using System.Security.Claims;

namespace ERP.NSQuell.Controllers;

[ResponseCache(NoStore=true,Location=ResponseCacheLocation.None)]
public sealed class ProduccionFlujoController : Controller
{
    private readonly IConfiguration _configuration;
    public ProduccionFlujoController(IConfiguration configuration)=>_configuration=configuration;
    private string ConnectionString=>_configuration.GetConnectionString("DefaultConnection")??throw new InvalidOperationException("No se encontro DefaultConnection.");
    private int UsuarioID=>int.TryParse(User.FindFirstValue(ClaimTypes.NameIdentifier)??User.FindFirstValue("UsuarioID"),out var id)?id:0;
    private string UsuarioNombre=>User.Identity?.Name??User.FindFirstValue(ClaimTypes.Name)??"Usuario ERP";

    [HttpGet] public async Task<IActionResult> Index(string? q,string? estado,CancellationToken ct){var vm=new ProduccionFlujoIndexVm{Busqueda=q?.Trim(),Estado=estado?.Trim().ToUpperInvariant()};await using var cn=new SqlConnection(ConnectionString);await cn.OpenAsync(ct);const string sql=@"SELECT * FROM dbo.vw_Produccion_TableroIntegral WHERE Activo=1 AND (@Q IS NULL OR NumeroOF LIKE N'%'+@Q+N'%' OR ClienteNombre LIKE N'%'+@Q+N'%' OR NumeroParte LIKE N'%'+@Q+N'%' OR MaquinaCodigo LIKE N'%'+@Q+N'%') AND (@Estado IS NULL OR CodigoEstatusFlujo=@Estado) ORDER BY CASE CodigoEstatusFlujo WHEN N'EN_PROCESO' THEN 0 WHEN N'ESPERANDO_CALIDAD' THEN 1 WHEN N'DETENIDA_CALIDAD' THEN 2 WHEN N'LIBERADA' THEN 3 ELSE 4 END,FechaModificacion DESC,EjecucionProduccionID DESC";await using var cmd=new SqlCommand(sql,cn);cmd.Parameters.Add("@Q",SqlDbType.NVarChar,250).Value=string.IsNullOrWhiteSpace(vm.Busqueda)?DBNull.Value:vm.Busqueda;cmd.Parameters.Add("@Estado",SqlDbType.NVarChar,40).Value=string.IsNullOrWhiteSpace(vm.Estado)?DBNull.Value:vm.Estado;await using var rd=await cmd.ExecuteReaderAsync(ct);while(await rd.ReadAsync(ct))vm.Items.Add(MapItem(rd));return View(vm);}

    [HttpGet] public async Task<IActionResult> Detalle(int id,CancellationToken ct){var vm=new ProduccionFlujoDetalleVm();await using var cn=new SqlConnection(ConnectionString);await cn.OpenAsync(ct);await using(var cmd=new SqlCommand("SELECT * FROM dbo.vw_Produccion_TableroIntegral WHERE EjecucionProduccionID=@Id",cn)){cmd.Parameters.Add("@Id",SqlDbType.Int).Value=id;await using var rd=await cmd.ExecuteReaderAsync(ct);if(!await rd.ReadAsync(ct))return NotFound();vm.Ejecucion=MapItem(rd);}vm.UsuarioEsCalidad=await EsCalidadAsync(cn,ct);await CargarDetalleAsync(cn,id,vm,ct);return View(vm);}

    [HttpPost,ValidateAntiForgeryToken] public Task<IActionResult> Preparar(int id,string turno,CancellationToken ct)=>EjecutarProcAsync("dbo.sp_Produccion_Preparar",id,ct,("@Turno",turno));
    [HttpPost,ValidateAntiForgeryToken] public Task<IActionResult> SolicitarLiberacion(int id,CancellationToken ct)=>EjecutarProcAsync("dbo.sp_Produccion_SolicitarLiberacion",id,ct);
    [HttpPost,ValidateAntiForgeryToken] public Task<IActionResult> CambiarEstado(int id,string accion,string? observaciones,CancellationToken ct)=>EjecutarProcAsync("dbo.sp_Produccion_CambiarEstado",id,ct,("@Accion",accion),("@Observaciones",observaciones));
    [HttpPost,ValidateAntiForgeryToken] public Task<IActionResult> IniciarParo(int id,string motivo,string descripcion,CancellationToken ct)=>EjecutarProcAsync("dbo.sp_Produccion_IniciarParo",id,ct,("@Motivo",motivo),("@Descripcion",descripcion));
    [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> CerrarParo(int id,int paroID,CancellationToken ct){await using var cn=new SqlConnection(ConnectionString);await cn.OpenAsync(ct);await using var cmd=new SqlCommand("dbo.sp_Produccion_CerrarParo",cn){CommandType=CommandType.StoredProcedure};cmd.Parameters.Add("@ParoID",SqlDbType.Int).Value=paroID;AgregarUsuario(cmd);return await EjecutarYVolverAsync(cmd,id,ct);}
    [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> RegistrarHora(ProduccionHoraFormVm model,CancellationToken ct){await using var cn=new SqlConnection(ConnectionString);await cn.OpenAsync(ct);await using var cmd=new SqlCommand("dbo.sp_Produccion_RegistrarHoraIntegral",cn){CommandType=CommandType.StoredProcedure};cmd.Parameters.Add("@EjecucionID",SqlDbType.Int).Value=model.EjecucionID;cmd.Parameters.Add("@Fecha",SqlDbType.Date).Value=model.Fecha.Date;cmd.Parameters.Add("@HoraInicio",SqlDbType.Time).Value=model.HoraInicio;cmd.Parameters.Add("@HoraFin",SqlDbType.Time).Value=model.HoraFin;cmd.Parameters.Add("@OK",SqlDbType.Int).Value=model.OK;cmd.Parameters.Add("@Sospechosa",SqlDbType.Int).Value=model.Sospechosa;cmd.Parameters.Add("@Scrap",SqlDbType.Int).Value=model.Scrap;cmd.Parameters.Add("@Turno",SqlDbType.NVarChar,30).Value=model.Turno??"";cmd.Parameters.Add("@EtiquetaInicial",SqlDbType.NVarChar,120).Value=Db(model.EtiquetaInicial);cmd.Parameters.Add("@EtiquetaFinal",SqlDbType.NVarChar,120).Value=Db(model.EtiquetaFinal);cmd.Parameters.Add("@Defecto",SqlDbType.NVarChar,200).Value=Db(model.Defecto);cmd.Parameters.Add("@Observaciones",SqlDbType.NVarChar,500).Value=Db(model.Observaciones);AgregarUsuario(cmd);return await EjecutarYVolverAsync(cmd,model.EjecucionID,ct);}
    [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> ConfirmarMaterial(int id,string modulo,long movimientoID,string? observaciones,CancellationToken ct){await using var cn=new SqlConnection(ConnectionString);await cn.OpenAsync(ct);await using var tx=(SqlTransaction)await cn.BeginTransactionAsync(ct);try{const string valid=@"SELECT TOP(1) t.Codigo,t.Descripcion,t.Cantidad,t.Unidad FROM dbo.vw_AlmacenOF_TrazabilidadEntregas t INNER JOIN dbo.Produccion_Ejecucion e ON e.SolicitudProduccionID=t.SolicitudProduccionID WHERE e.EjecucionProduccionID=@Ejecucion AND t.Modulo=@Modulo AND t.MovimientoID=@Movimiento AND t.Activo=1";string codigo,descripcion,unidad;decimal cantidad;await using(var cmd=new SqlCommand(valid,cn,tx)){cmd.Parameters.Add("@Ejecucion",SqlDbType.Int).Value=id;cmd.Parameters.Add("@Modulo",SqlDbType.NVarChar,20).Value=modulo;cmd.Parameters.Add("@Movimiento",SqlDbType.BigInt).Value=movimientoID;await using var rd=await cmd.ExecuteReaderAsync(ct);if(!await rd.ReadAsync(ct))throw new InvalidOperationException("La entrega no pertenece a esta ejecucion.");codigo=Convert.ToString(rd["Codigo"])??"";descripcion=Convert.ToString(rd["Descripcion"])??"";cantidad=Convert.ToDecimal(rd["Cantidad"]);unidad=Convert.ToString(rd["Unidad"])??"";}const string ins=@"IF NOT EXISTS(SELECT 1 FROM dbo.Produccion_RecepcionMaterial WHERE Modulo=@Modulo AND MovimientoID=@Movimiento) INSERT dbo.Produccion_RecepcionMaterial(EjecucionProduccionID,Modulo,MovimientoID,Codigo,Descripcion,Cantidad,Unidad,RecibidoPorUsuarioID,Observaciones) VALUES(@Ejecucion,@Modulo,@Movimiento,@Codigo,@Descripcion,@Cantidad,@Unidad,@Usuario,@Obs);";await using(var cmd=new SqlCommand(ins,cn,tx)){cmd.Parameters.Add("@Ejecucion",SqlDbType.Int).Value=id;cmd.Parameters.Add("@Modulo",SqlDbType.NVarChar,20).Value=modulo;cmd.Parameters.Add("@Movimiento",SqlDbType.BigInt).Value=movimientoID;cmd.Parameters.Add("@Codigo",SqlDbType.NVarChar,100).Value=codigo;cmd.Parameters.Add("@Descripcion",SqlDbType.NVarChar,300).Value=descripcion;var p=cmd.Parameters.Add("@Cantidad",SqlDbType.Decimal);p.Precision=18;p.Scale=3;p.Value=cantidad;cmd.Parameters.Add("@Unidad",SqlDbType.NVarChar,20).Value=unidad;cmd.Parameters.Add("@Usuario",SqlDbType.Int).Value=UsuarioID;cmd.Parameters.Add("@Obs",SqlDbType.NVarChar,500).Value=Db(observaciones);await cmd.ExecuteNonQueryAsync(ct);}await using(var ev=new SqlCommand("dbo.sp_Produccion_RegistrarEvento",cn,tx){CommandType=CommandType.StoredProcedure}){ev.Parameters.Add("@EjecucionID",SqlDbType.Int).Value=id;ev.Parameters.Add("@Tipo",SqlDbType.NVarChar,50).Value="RECEPCION_MATERIAL";ev.Parameters.Add("@Anterior",SqlDbType.NVarChar,40).Value=DBNull.Value;ev.Parameters.Add("@Nuevo",SqlDbType.NVarChar,40).Value=DBNull.Value;ev.Parameters.Add("@Descripcion",SqlDbType.NVarChar,800).Value=$"Recepcion confirmada: {modulo} {codigo}, {cantidad:0.###} {unidad}.";ev.Parameters.Add("@UsuarioID",SqlDbType.Int).Value=UsuarioID;ev.Parameters.Add("@UsuarioNombre",SqlDbType.NVarChar,180).Value=UsuarioNombre;ev.Parameters.Add("@Tabla",SqlDbType.NVarChar,80).Value="Produccion_RecepcionMaterial";ev.Parameters.Add("@ReferenciaID",SqlDbType.BigInt).Value=movimientoID;await ev.ExecuteNonQueryAsync(ct);}await tx.CommitAsync(ct);TempData["ProdOk"]="Recepcion de material confirmada.";}catch(Exception ex){await tx.RollbackAsync(ct);TempData["ProdError"]=ex.Message;}return RedirectToAction(nameof(Detalle),new{id});}
    [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> ResolverCalidad(int id,bool aprobado,string observaciones,CancellationToken ct){await using var cn=new SqlConnection(ConnectionString);await cn.OpenAsync(ct);if(!await EsCalidadAsync(cn,ct)){TempData["ProdError"]="Solo Calidad puede resolver el checklist.";return RedirectToAction(nameof(Detalle),new{id});}await using var cmd=new SqlCommand("dbo.sp_Produccion_ResolverChecklist",cn){CommandType=CommandType.StoredProcedure};cmd.Parameters.Add("@EjecucionID",SqlDbType.Int).Value=id;cmd.Parameters.Add("@Aprobado",SqlDbType.Bit).Value=aprobado;cmd.Parameters.Add("@Observaciones",SqlDbType.NVarChar,1000).Value=observaciones??"";AgregarUsuario(cmd);return await EjecutarYVolverAsync(cmd,id,ct);}
    [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> FormarCaja(int id,string etiqueta,int cantidad,CancellationToken ct){await using var cn=new SqlConnection(ConnectionString);await cn.OpenAsync(ct);await using var cmd=new SqlCommand("dbo.sp_Produccion_FormarCaja",cn){CommandType=CommandType.StoredProcedure};cmd.Parameters.Add("@EjecucionID",SqlDbType.Int).Value=id;cmd.Parameters.Add("@Etiqueta",SqlDbType.NVarChar,150).Value=etiqueta;cmd.Parameters.Add("@Cantidad",SqlDbType.Int).Value=cantidad;AgregarUsuario(cmd);return await EjecutarYVolverAsync(cmd,id,ct);}
    [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> LiberarCaja(int id,long cajaID,string estatus,CancellationToken ct){await using var cn=new SqlConnection(ConnectionString);await cn.OpenAsync(ct);if(!await EsCalidadAsync(cn,ct)){TempData["ProdError"]="Solo Calidad puede asignar el estatus de caja.";return RedirectToAction(nameof(Detalle),new{id});}estatus=(estatus??"").Trim().ToUpperInvariant();if(estatus is not("VERDE" or "AMARILLO" or "ROJO" or "GP12")){TempData["ProdError"]="Estatus de caja no valido.";return RedirectToAction(nameof(Detalle),new{id});}await using var tx=(SqlTransaction)await cn.BeginTransactionAsync(ct);try{await using(var cmd=new SqlCommand("UPDATE dbo.Produccion_Cajas SET EstatusCalidad=@Estatus,FechaLiberacionCalidad=SYSDATETIME(),AuditorCalidadUsuarioID=@Usuario WHERE CajaProduccionID=@Caja AND EjecucionProduccionID=@Ejecucion AND Activo=1",cn,tx)){cmd.Parameters.Add("@Estatus",SqlDbType.NVarChar,20).Value=estatus;cmd.Parameters.Add("@Usuario",SqlDbType.Int).Value=UsuarioID;cmd.Parameters.Add("@Caja",SqlDbType.BigInt).Value=cajaID;cmd.Parameters.Add("@Ejecucion",SqlDbType.Int).Value=id;await cmd.ExecuteNonQueryAsync(ct);}await using(var ev=new SqlCommand("dbo.sp_Produccion_RegistrarEvento",cn,tx){CommandType=CommandType.StoredProcedure}){ev.Parameters.Add("@EjecucionID",SqlDbType.Int).Value=id;ev.Parameters.Add("@Tipo",SqlDbType.NVarChar,50).Value="CALIDAD_CAJA";ev.Parameters.Add("@Anterior",SqlDbType.NVarChar,40).Value=DBNull.Value;ev.Parameters.Add("@Nuevo",SqlDbType.NVarChar,40).Value=estatus;ev.Parameters.Add("@Descripcion",SqlDbType.NVarChar,800).Value=$"Caja {cajaID} clasificada {estatus}.";ev.Parameters.Add("@UsuarioID",SqlDbType.Int).Value=UsuarioID;ev.Parameters.Add("@UsuarioNombre",SqlDbType.NVarChar,180).Value=UsuarioNombre;ev.Parameters.Add("@Tabla",SqlDbType.NVarChar,80).Value="Produccion_Cajas";ev.Parameters.Add("@ReferenciaID",SqlDbType.BigInt).Value=cajaID;await ev.ExecuteNonQueryAsync(ct);}await tx.CommitAsync(ct);TempData["ProdOk"]="Estatus de caja actualizado.";}catch(Exception ex){await tx.RollbackAsync(ct);TempData["ProdError"]=ex.Message;}return RedirectToAction(nameof(Detalle),new{id});}
    [HttpPost,ValidateAntiForgeryToken] public Task<IActionResult> CerrarTransferir(int id,CancellationToken ct)=>EjecutarProcAsync("dbo.sp_Produccion_CerrarYTransferir",id,ct);
    [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> AsignarPersonal(int id,int usuarioID,string rol,string turno,CancellationToken ct){rol=(rol??"").Trim().ToUpperInvariant();var permitidos=new[]{"AUXILIAR","TECNICO","ENCARGADO","OPERADOR","SUPERVISOR"};if(!permitidos.Contains(rol)){TempData["ProdError"]="Rol operativo no valido.";return RedirectToAction(nameof(Detalle),new{id});}await using var cn=new SqlConnection(ConnectionString);await cn.OpenAsync(ct);const string sql=@"UPDATE dbo.Produccion_Asignaciones SET Activo=0,FechaFin=SYSDATETIME() WHERE EjecucionProduccionID=@Ejecucion AND UsuarioID=@Usuario AND RolOperacion=@Rol AND Activo=1; INSERT dbo.Produccion_Asignaciones(EjecucionProduccionID,UsuarioID,RolOperacion,Turno,UsuarioRegistraID) VALUES(@Ejecucion,@Usuario,@Rol,@Turno,@Registra);";await using var cmd=new SqlCommand(sql,cn);cmd.Parameters.Add("@Ejecucion",SqlDbType.Int).Value=id;cmd.Parameters.Add("@Usuario",SqlDbType.Int).Value=usuarioID;cmd.Parameters.Add("@Rol",SqlDbType.NVarChar,40).Value=rol;cmd.Parameters.Add("@Turno",SqlDbType.NVarChar,30).Value=turno??"";cmd.Parameters.Add("@Registra",SqlDbType.Int).Value=UsuarioID;try{await cmd.ExecuteNonQueryAsync(ct);TempData["ProdOk"]="Personal asignado.";}catch(Exception ex){TempData["ProdError"]=ex.Message;}return RedirectToAction(nameof(Detalle),new{id});}

    private async Task<IActionResult> EjecutarProcAsync(string proc,int id,CancellationToken ct,params (string Name,object? Value)[] values){await using var cn=new SqlConnection(ConnectionString);await cn.OpenAsync(ct);await using var cmd=new SqlCommand(proc,cn){CommandType=CommandType.StoredProcedure};cmd.Parameters.Add("@EjecucionID",SqlDbType.Int).Value=id;foreach(var v in values)cmd.Parameters.AddWithValue(v.Name,v.Value??DBNull.Value);AgregarUsuario(cmd);return await EjecutarYVolverAsync(cmd,id,ct);}
    private async Task<IActionResult> EjecutarYVolverAsync(SqlCommand cmd,int id,CancellationToken ct){try{await cmd.ExecuteNonQueryAsync(ct);TempData["ProdOk"]="Operacion registrada.";}catch(Exception ex){TempData["ProdError"]=ex.Message;}return RedirectToAction(nameof(Detalle),new{id});}
    private void AgregarUsuario(SqlCommand cmd){cmd.Parameters.Add("@UsuarioID",SqlDbType.Int).Value=UsuarioID;cmd.Parameters.Add("@UsuarioNombre",SqlDbType.NVarChar,180).Value=UsuarioNombre;}
    private static object Db(string? value)=>string.IsNullOrWhiteSpace(value)?DBNull.Value:value.Trim();
    private static ProduccionFlujoItemVm MapItem(SqlDataReader rd)=>new(){EjecucionProduccionID=Convert.ToInt32(rd["EjecucionProduccionID"]),NumeroOF=Convert.ToString(rd["NumeroOF"])??"",Cliente=Convert.ToString(rd["ClienteNombre"])??"",NumeroParte=Convert.ToString(rd["NumeroParte"])??"",Descripcion=Convert.ToString(rd["DescripcionParte"])??"",Maquina=$"{Convert.ToString(rd["MaquinaCodigo"])} {Convert.ToString(rd["MaquinaNombre"])}".Trim(),Molde=Convert.ToString(rd["MoldeCodigo"])??"",Turno=Convert.ToString(rd["Turno"])??"",CantidadPlaneada=Convert.ToInt32(rd["CantidadPlaneada"]),CantidadOK=Convert.ToInt32(rd["CantidadOKTotal"]),Sospechosa=Convert.ToInt32(rd["CantidadSospechosaTotal"]),Scrap=Convert.ToInt32(rd["CantidadScrapTotal"]),Avance=Convert.ToDecimal(rd["PorcentajeAvance"]),Estado=Convert.ToString(rd["CodigoEstatusFlujo"])??"",ChecklistAprobado=Convert.ToBoolean(rd["ChecklistAprobado"]),RequiereReliberacion=Convert.ToBoolean(rd["RequiereReliberacion"]),PersonalAsignado=Convert.ToInt32(rd["PersonalAsignado"]),ParosAbiertos=Convert.ToInt32(rd["ParosAbiertos"]),CajasFormadas=Convert.ToInt32(rd["CajasFormadas"])};
    private async Task<bool> EsCalidadAsync(SqlConnection cn,CancellationToken ct){await using var cmd=new SqlCommand("SELECT COUNT(*) FROM dbo.Usuarios u LEFT JOIN dbo.Departamentos d ON d.DepartamentoID=u.DepartamentoID WHERE u.UsuarioID=@Id AND UPPER(ISNULL(d.NombreDepartamento,N'')) LIKE N'%CALIDAD%'",cn);cmd.Parameters.Add("@Id",SqlDbType.Int).Value=UsuarioID;return Convert.ToInt32(await cmd.ExecuteScalarAsync(ct)??0)>0;}
    private static async Task CargarDetalleAsync(SqlConnection cn,int id,ProduccionFlujoDetalleVm vm,CancellationToken ct){
        await using(var cmd=new SqlCommand("SELECT TOP(100) FechaEvento,TipoEvento,ISNULL(Descripcion,N'') Descripcion,ISNULL(UsuarioNombre,N'') UsuarioNombre,ISNULL(EstadoNuevo,N'') EstadoNuevo FROM dbo.Produccion_Eventos WHERE EjecucionProduccionID=@Id ORDER BY FechaEvento DESC,EventoID DESC",cn)){cmd.Parameters.Add("@Id",SqlDbType.Int).Value=id;await using var rd=await cmd.ExecuteReaderAsync(ct);while(await rd.ReadAsync(ct))vm.Eventos.Add(new(){Fecha=Convert.ToDateTime(rd["FechaEvento"]),Tipo=Convert.ToString(rd["TipoEvento"])??"",Descripcion=Convert.ToString(rd["Descripcion"])??"",Usuario=Convert.ToString(rd["UsuarioNombre"])??"",EstadoNuevo=Convert.ToString(rd["EstadoNuevo"])??""});}
        await using(var cmd=new SqlCommand("SELECT RegistroHoraID,FechaProduccion,HoraInicio,HoraFin,CantidadOK,CantidadSospechosa,CantidadScrap,ISNULL(Turno,N'') Turno,ISNULL(DefectoPrincipal,N'') DefectoPrincipal FROM dbo.Produccion_RegistroHora WHERE EjecucionProduccionID=@Id AND Activo=1 ORDER BY FechaProduccion DESC,HoraInicio DESC",cn)){cmd.Parameters.Add("@Id",SqlDbType.Int).Value=id;await using var rd=await cmd.ExecuteReaderAsync(ct);while(await rd.ReadAsync(ct))vm.Capturas.Add(new(){RegistroHoraID=Convert.ToInt32(rd["RegistroHoraID"]),Fecha=Convert.ToDateTime(rd["FechaProduccion"]),Inicio=(TimeSpan)rd["HoraInicio"],Fin=(TimeSpan)rd["HoraFin"],OK=Convert.ToInt32(rd["CantidadOK"]),Sospechosa=Convert.ToInt32(rd["CantidadSospechosa"]),Scrap=Convert.ToInt32(rd["CantidadScrap"]),Turno=Convert.ToString(rd["Turno"])??"",Defecto=Convert.ToString(rd["DefectoPrincipal"])??""});}
        await using(var cmd=new SqlCommand("SELECT ParoID,FechaInicioParo,FechaFinParo,DuracionMinutos,ISNULL(MotivoParoTexto,N'') Motivo,ISNULL(RequiereReliberacion,0) Requiere FROM dbo.Produccion_Paros WHERE EjecucionProduccionID=@Id AND Activo=1 ORDER BY FechaInicioParo DESC",cn)){cmd.Parameters.Add("@Id",SqlDbType.Int).Value=id;await using var rd=await cmd.ExecuteReaderAsync(ct);while(await rd.ReadAsync(ct))vm.Paros.Add(new(){ParoID=Convert.ToInt32(rd["ParoID"]),Inicio=Convert.ToDateTime(rd["FechaInicioParo"]),Fin=rd["FechaFinParo"]==DBNull.Value?null:Convert.ToDateTime(rd["FechaFinParo"]),Minutos=rd["DuracionMinutos"]==DBNull.Value?null:Convert.ToInt32(rd["DuracionMinutos"]),Motivo=Convert.ToString(rd["Motivo"])??"",RequiereReliberacion=Convert.ToBoolean(rd["Requiere"])});}
        await using(var cmd=new SqlCommand("SELECT CajaProduccionID,NumeroCaja,Etiqueta,Cantidad,EstatusCalidad,FechaFormacion FROM dbo.Produccion_Cajas WHERE EjecucionProduccionID=@Id AND Activo=1 ORDER BY NumeroCaja DESC",cn)){cmd.Parameters.Add("@Id",SqlDbType.Int).Value=id;await using var rd=await cmd.ExecuteReaderAsync(ct);while(await rd.ReadAsync(ct))vm.Cajas.Add(new(){CajaProduccionID=Convert.ToInt64(rd["CajaProduccionID"]),NumeroCaja=Convert.ToInt32(rd["NumeroCaja"]),Etiqueta=Convert.ToString(rd["Etiqueta"])??"",Cantidad=Convert.ToInt32(rd["Cantidad"]),EstatusCalidad=Convert.ToString(rd["EstatusCalidad"])??"",Fecha=Convert.ToDateTime(rd["FechaFormacion"])});}
        const string material=@"SELECT t.Modulo,t.MovimientoID,t.Codigo,t.Descripcion,ISNULL(t.Variante,N'') Variante,t.Cantidad,t.Unidad,ISNULL(t.EntregadoPor,N'') EntregadoPor,t.FechaMovimiento FROM dbo.vw_AlmacenOF_TrazabilidadEntregas t INNER JOIN dbo.Produccion_Ejecucion e ON e.SolicitudProduccionID=t.SolicitudProduccionID WHERE e.EjecucionProduccionID=@Id AND t.Activo=1 AND NOT EXISTS(SELECT 1 FROM dbo.Produccion_RecepcionMaterial r WHERE r.Modulo=t.Modulo AND r.MovimientoID=t.MovimientoID) ORDER BY t.FechaMovimiento";await using(var cmd=new SqlCommand(material,cn)){cmd.Parameters.Add("@Id",SqlDbType.Int).Value=id;await using var rd=await cmd.ExecuteReaderAsync(ct);while(await rd.ReadAsync(ct))vm.MaterialPendienteRecepcion.Add(new(){Modulo=Convert.ToString(rd["Modulo"])??"",MovimientoID=Convert.ToInt64(rd["MovimientoID"]),Codigo=Convert.ToString(rd["Codigo"])??"",Descripcion=Convert.ToString(rd["Descripcion"])??"",Variante=Convert.ToString(rd["Variante"])??"",Cantidad=Convert.ToDecimal(rd["Cantidad"]),Unidad=Convert.ToString(rd["Unidad"])??"",EntregadoPor=Convert.ToString(rd["EntregadoPor"])??"",Fecha=Convert.ToDateTime(rd["FechaMovimiento"])});}
        const string people=@"SELECT u.UsuarioID,CONCAT(p.Nombre,N' ',ISNULL(p.ApellidoPaterno,N''),N' ',ISNULL(p.ApellidoMaterno,N'')) Nombre,ISNULL(p.Puesto,N'Produccion') Puesto FROM dbo.Usuarios u INNER JOIN dbo.Persona p ON p.PersonaID=u.PersonaID LEFT JOIN dbo.Departamentos d ON d.DepartamentoID=u.DepartamentoID WHERE ISNULL(u.Activo,1)=1 AND p.EsColaboradorActivo=1 AND UPPER(ISNULL(d.NombreDepartamento,N'')) LIKE N'%PRODUC%' ORDER BY p.Nombre,p.ApellidoPaterno";await using(var cmd=new SqlCommand(people,cn))await using(var rd=await cmd.ExecuteReaderAsync(ct))while(await rd.ReadAsync(ct))vm.PersonalDisponible.Add(new(){UsuarioID=Convert.ToInt32(rd["UsuarioID"]),Nombre=Convert.ToString(rd["Nombre"])??"",Puesto=Convert.ToString(rd["Puesto"])??""});
    }
}
